/**
 * Report and hide for a shared notebook: the one place in Lexpad where
 * somebody sees words another person wrote (App Store Review Guideline 1.2,
 * user-generated content; Google Play's UGC policy).
 *
 * Report: signed in, the same sheet as an AI report, sent to the team's
 * inbox (Settings → Send feedback's endpoint, so it waits in the outbox when
 * offline); signed out, an e-mail to the support address with the link
 * already in it. The team removes a notebook that breaks the terms, and an
 * operator can close the account that shared it.
 *
 * Hide: this device stops showing that notebook, at once and without
 * waiting for anybody. It is remembered in the small preferences store, so
 * it survives signing out, and it can be undone from the same page.
 */
import { useState } from 'react';
import type { ApiSharedNotebook } from '@/api/types.js';
import { ReportSheet } from '@/features/report/ReportSheet.js';
import type { ReportTarget } from '@/features/report/report.js';
import { snapshotOf } from '@/features/report/report.js';
import { feedbackContext, sendFeedback } from '@/features/settings/feedback.js';
import { t } from '@/i18n/index.js';
import { setShareHidden, shareReportBody, shareReportMailto } from './moderation.js';
import reportStyles from '@/features/report/Report.module.css';
import styles from './SharedNotebook.module.css';

/** The quiet row under a shared notebook: Report and Hide. */
export function ShareModeration({
  shareId,
  notebook,
  signedIn,
  onHide,
}: {
  shareId: string;
  notebook: ApiSharedNotebook;
  signedIn: boolean;
  onHide: () => void;
}): React.JSX.Element {
  const [reporting, setReporting] = useState(false);
  const target: ReportTarget = {
    surface: 'word',
    snapshot: snapshotOf([notebook.title, ...notebook.words.slice(0, 5).map((word) => word.headword)]),
  };
  return (
    <div className={styles.moderation}>
      {signedIn ? (
        <button
          type="button"
          className={reportStyles.textButton}
          onClick={() => {
            setReporting(true);
          }}
        >
          {t('shareReport.action')}
        </button>
      ) : (
        <a className={reportStyles.textButton} href={shareReportMailto(shareId)}>
          {t('shareReport.action')}
        </a>
      )}
      <button
        type="button"
        className={reportStyles.textButton}
        onClick={() => {
          setShareHidden(shareId, true);
          onHide();
        }}
      >
        {t('shareReport.hide')}
      </button>
      {reporting && (
        <ReportSheet
          target={target}
          lead={t('shareReport.lead')}
          send={async (reason, note) => {
            await sendFeedback(
              shareReportBody(shareId, notebook, reason, note),
              await feedbackContext(`/s/${shareId}`),
            );
          }}
          onClose={() => {
            setReporting(false);
          }}
        />
      )}
    </div>
  );
}
