/**
 * The parts of Report and Hide for a shared notebook that are not a screen:
 * which links this device has hidden, and what a report says. The screen is
 * ShareModeration.tsx.
 */
import type { ApiAiReportReason, ApiSharedNotebook } from '@/api/types.js';
import { snapshotOf } from '@/features/report/report.js';
import { FEEDBACK_MAX_CHARS } from '@/features/settings/feedback.js';
import { t } from '@/i18n/index.js';
import { platform } from '@/lib/platform/index.js';

const HIDDEN_KEY = 'wb.hiddenShares';
/** How many hidden links a device remembers; the oldest is forgotten first. */
const HIDDEN_MAX = 200;
/** Where a report goes from somebody who is not signed in. */
const SUPPORT_EMAIL = 'hello@lexpad.app';
/** The public address of a shared notebook, as the report names it. */
const SHARE_ORIGIN = 'https://app.lexpad.app';

function hiddenList(): string[] {
  try {
    const raw = JSON.parse(platform.prefs.get(HIDDEN_KEY) ?? '[]') as unknown;
    return Array.isArray(raw) ? raw.filter((id): id is string => typeof id === 'string') : [];
  } catch {
    return [];
  }
}

/** Whether this device has hidden the shared notebook. */
export function isShareHidden(shareId: string): boolean {
  return hiddenList().includes(shareId);
}

/** Hides or shows a shared notebook on this device. */
export function setShareHidden(shareId: string, hidden: boolean): void {
  const rest = hiddenList().filter((id) => id !== shareId);
  const next = hidden ? [...rest, shareId].slice(-HIDDEN_MAX) : rest;
  platform.prefs.set(HIDDEN_KEY, JSON.stringify(next));
}

/** The report as the team reads it: the link, why, the note, then what was shown. */
export function shareReportBody(
  shareId: string,
  notebook: ApiSharedNotebook,
  reason: ApiAiReportReason,
  note: string,
): string {
  const head = [
    'Report of a shared notebook',
    `Link: ${SHARE_ORIGIN}/s/${shareId}`,
    `Reason: ${reason}`,
    note.trim() === '' ? undefined : `Note: ${note.trim()}`,
    '---',
  ]
    .filter((line): line is string => line !== undefined)
    .join('\n');
  const shown = snapshotOf([
    notebook.title,
    ...notebook.words.map((word) => [word.headword, word.meanings?.[0]?.meaning].filter(Boolean).join(' — ')),
  ]);
  return [...`${head}\n${shown}`].slice(0, FEEDBACK_MAX_CHARS).join('');
}

/** The mailto: link for somebody who is not signed in. */
export function shareReportMailto(shareId: string): string {
  const subject = `Report: shared notebook ${shareId}`;
  const body = `${SHARE_ORIGIN}/s/${shareId}\n\n${t('shareReport.mailBody')}`;
  return `mailto:${SUPPORT_EMAIL}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
}
